from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from openpyxl import load_workbook
from pptx import Presentation

try:
    import pdfplumber
except Exception:  # pragma: no cover
    pdfplumber = None

try:
    from docx import Document
except Exception:  # pragma: no cover
    Document = None


ROOT = Path(r"C:\Users\win\Desktop\敖钦储能项目")
SOURCE = ROOT / "原始需求"
OUT = ROOT / "tools" / "requirement_extract"


def cell_text(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).replace("\n", " ").strip()
    return text


def write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def shape_text(shape: Any) -> list[str]:
    parts: list[str] = []
    if hasattr(shape, "text") and shape.text:
        parts.append(shape.text.strip())
    if hasattr(shape, "has_table") and shape.has_table:
        rows: list[str] = []
        for row in shape.table.rows:
            values = [cell_text(cell.text) for cell in row.cells]
            if any(values):
                rows.append(" | ".join(values))
        if rows:
            parts.append("\n".join(rows))
    if hasattr(shape, "shapes"):
        for sub_shape in shape.shapes:
            parts.extend(shape_text(sub_shape))
    return [part for part in parts if part]


def extract_pptx(path: Path) -> dict[str, Any]:
    prs = Presentation(path)
    slides: list[dict[str, Any]] = []
    md = [f"# {path.name}", ""]
    for idx, slide in enumerate(prs.slides, start=1):
        texts: list[str] = []
        for shape in slide.shapes:
            texts.extend(shape_text(shape))
        title = texts[0].splitlines()[0] if texts else ""
        slides.append({"slide": idx, "title": title, "text": texts})
        md.append(f"## Slide {idx}: {title}")
        for text in texts:
            md.append(text)
            md.append("")
    write_text(OUT / "pptx" / f"{path.stem}.md", "\n".join(md))
    return {"type": "pptx", "path": str(path), "slide_count": len(slides), "slides": slides}


def sample_sheet(ws: Any, max_rows: int = 12, max_cols: int = 24) -> list[list[str]]:
    rows: list[list[str]] = []
    row_limit = min(ws.max_row or 0, max_rows)
    col_limit = min(ws.max_column or 0, max_cols)
    for row in ws.iter_rows(min_row=1, max_row=row_limit, min_col=1, max_col=col_limit):
        values = [cell_text(cell.value) for cell in row]
        if any(values):
            rows.append(values)
    return rows


def extract_xlsx(path: Path) -> dict[str, Any]:
    wb = load_workbook(path, data_only=False, read_only=False)
    book: dict[str, Any] = {
        "type": "xlsx",
        "path": str(path),
        "sheet_names": wb.sheetnames,
        "sheets": [],
    }
    md = [f"# {path.name}", ""]
    for ws in wb.worksheets:
        formulas: list[dict[str, str]] = []
        comments: list[dict[str, str]] = []
        non_empty = 0
        for row in ws.iter_rows():
            for cell in row:
                if cell.value is not None:
                    non_empty += 1
                    if isinstance(cell.value, str) and cell.value.startswith("=") and len(formulas) < 30:
                        formulas.append({"cell": cell.coordinate, "formula": cell.value})
                if cell.comment is not None and len(comments) < 30:
                    comments.append({"cell": cell.coordinate, "comment": cell.comment.text})
        merged_ranges = [str(rng) for rng in list(ws.merged_cells.ranges)[:60]]
        sheet = {
            "name": ws.title,
            "max_row": ws.max_row,
            "max_column": ws.max_column,
            "non_empty_cells": non_empty,
            "freeze_panes": str(ws.freeze_panes) if ws.freeze_panes else "",
            "merged_range_count": len(ws.merged_cells.ranges),
            "merged_ranges_sample": merged_ranges,
            "formula_sample": formulas,
            "comment_sample": comments,
            "sample_rows": sample_sheet(ws),
        }
        book["sheets"].append(sheet)
        md.append(f"## {ws.title}")
        md.append(f"- size: {ws.max_row} rows x {ws.max_column} columns")
        md.append(f"- non_empty_cells: {non_empty}")
        md.append(f"- freeze_panes: {sheet['freeze_panes'] or 'none'}")
        md.append(f"- merged_range_count: {sheet['merged_range_count']}")
        if formulas:
            md.append("- formula_sample:")
            for item in formulas[:10]:
                md.append(f"  - {item['cell']}: `{item['formula']}`")
        if comments:
            md.append("- comment_sample:")
            for item in comments[:10]:
                md.append(f"  - {item['cell']}: {item['comment']}")
        md.append("")
        md.append("| " + " | ".join([f"c{i}" for i in range(1, 25)]) + " |")
        md.append("|" + "|".join(["---"] * 24) + "|")
        for row in sheet["sample_rows"]:
            padded = (row + [""] * 24)[:24]
            md.append("| " + " | ".join(padded) + " |")
        md.append("")
    write_text(OUT / "xlsx" / f"{path.stem}.md", "\n".join(md))
    return book


def extract_docx(path: Path) -> dict[str, Any]:
    if Document is None:
        return {"type": "docx", "path": str(path), "error": "python-docx unavailable"}
    doc = Document(path)
    parts: list[str] = []
    for para in doc.paragraphs:
        text = para.text.strip()
        if text:
            parts.append(text)
    for table in doc.tables:
        for row in table.rows:
            values = [cell_text(cell.text) for cell in row.cells]
            if any(values):
                parts.append(" | ".join(values))
    text = "\n".join(parts)
    write_text(OUT / "docx" / f"{path.stem}.md", f"# {path.name}\n\n{text}")
    return {"type": "docx", "path": str(path), "text_chars": len(text)}


def extract_pdf(path: Path) -> dict[str, Any]:
    if pdfplumber is None:
        return {"type": "pdf", "path": str(path), "error": "pdfplumber unavailable"}
    pages: list[str] = []
    with pdfplumber.open(path) as pdf:
        for page in pdf.pages:
            pages.append(page.extract_text() or "")
    text = "\n\n".join(pages)
    write_text(OUT / "pdf" / f"{path.stem}.md", f"# {path.name}\n\n{text}")
    return {"type": "pdf", "path": str(path), "page_count": len(pages), "text_chars": len(text)}


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    results: list[dict[str, Any]] = []
    files = sorted([p for p in SOURCE.rglob("*") if p.is_file() and not p.name.startswith(("~$", ".~"))])
    for path in files:
        suffix = path.suffix.lower()
        try:
            if suffix == ".pptx":
                results.append(extract_pptx(path))
            elif suffix == ".xlsx":
                results.append(extract_xlsx(path))
            elif suffix == ".docx":
                results.append(extract_docx(path))
            elif suffix == ".pdf":
                results.append(extract_pdf(path))
            elif suffix in {".md", ".txt"}:
                rel = path.relative_to(SOURCE)
                write_text(OUT / "text" / rel.with_suffix(".md"), path.read_text(encoding="utf-8", errors="replace"))
                results.append({"type": "text", "path": str(path), "text_chars": path.stat().st_size})
            else:
                results.append({"type": suffix.lstrip(".") or "unknown", "path": str(path), "skipped": True})
        except Exception as exc:
            results.append({"type": suffix.lstrip(".") or "unknown", "path": str(path), "error": repr(exc)})
    write_text(OUT / "summary.json", json.dumps(results, ensure_ascii=False, indent=2))
    print(str(OUT))


if __name__ == "__main__":
    main()

