.dense-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.split-grid {
  display: grid;
  grid-template-columns: 320px minmax(0, 1fr);
  gap: 16px;
}

.workbench-grid {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr) 320px;
  gap: 16px;
  align-items: start;
}

.table-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 16px;
  align-items: start;
}

.workbench-grid > *,
.table-workspace > *,
.split-grid > *,
.dual-grid > *,
.triple-grid > *,
.quad-grid > * {
  min-width: 0;
}

.dual-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.triple-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.quad-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.overview-card {
  min-height: 176px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 14px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: #fff;
  padding: 16px;
}

.overview-card strong {
  display: block;
  margin-top: 14px;
  font-size: 24px;
  line-height: 1.1;
}

.overview-card p {
  margin: 10px 0 0;
  color: var(--color-text-sub);
  font-size: 13px;
  line-height: 1.6;
}

.flow-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.flow-step {
  min-height: 150px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background: var(--color-bg-soft);
  padding: 14px;
}

.flow-step strong {
  color: var(--color-primary-strong);
  font-size: 16px;
}

.flow-step p {
  margin: 0;
  color: var(--color-text-main);
  line-height: 1.6;
  font-size: 13px;
}

.flow-step span {
  color: var(--color-text-sub);
  font-size: 12px;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  background: rgba(29, 111, 165, 0.1);
  color: var(--color-primary-strong);
}

.demo-banner {
  border-radius: var(--radius-md);
  border: 1px dashed rgba(29, 111, 165, 0.35);
  background: rgba(29, 111, 165, 0.06);
  color: var(--color-primary-strong);
  padding: 10px 12px;
  font-size: 12px;
}

.status-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.status-item {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 14px;
  background: var(--color-bg-soft);
  border-radius: var(--radius-md);
}

.status-item strong {
  display: block;
  margin-bottom: 4px;
  font-size: 14px;
}

.status-item p {
  margin: 0;
  color: var(--color-text-sub);
  font-size: 13px;
}

.compact-list {
  display: grid;
  gap: 8px;
}

.trace-row {
  display: grid;
  grid-template-columns: minmax(76px, 108px) minmax(0, 1fr);
  gap: 10px;
  padding: 8px 0;
  border-bottom: 1px solid var(--color-border);
  font-size: 13px;
}

.trace-row:last-child {
  border-bottom: 0;
}

.trace-row span:first-child {
  color: var(--color-text-sub);
}

.trace-row strong,
.task-meta strong,
.status-item strong,
.status-item p,
.sheet-item p,
.issue-card span,
.quick-link-row span,
.formula-code,
.assistant-log code {
  overflow-wrap: anywhere;
}

.table-caption {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  color: var(--color-text-sub);
  font-size: 13px;
}

.formula-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background: linear-gradient(180deg, #fbfdff 0%, #f3f8fb 100%);
  padding: 14px;
}

.formula-code {
  font-family: var(--font-data);
  font-size: 13px;
  color: var(--color-primary-strong);
  background: rgba(29, 111, 165, 0.08);
  padding: 10px 12px;
  border-radius: var(--radius-sm);
}

.error-cell {
  background: rgba(197, 83, 83, 0.08);
  color: var(--color-danger);
  font-weight: 700;
}

.success-note {
  color: var(--color-success);
}

.warning-note {
  color: var(--color-warning);
}

.danger-note {
  color: var(--color-danger);
}

.assistant-reference {
  display: grid;
  gap: 8px;
}

.assistant-reference .reference-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 12px;
  background: var(--color-bg-panel);
}

.assistant-bubble {
  border-radius: var(--radius-md);
  padding: 12px 14px;
  font-size: 14px;
  line-height: 1.6;
}

.assistant-bubble.user {
  background: rgba(29, 111, 165, 0.08);
}

.assistant-bubble.bot {
  background: rgba(20, 138, 132, 0.08);
}

.assistant-log {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.assistant-log code {
  background: var(--color-bg-soft);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  color: var(--color-text-main);
  font-family: var(--font-data);
  font-size: 12px;
}

.assistant-mode-card {
  min-height: 220px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 14px;
  background: #fff;
}

.assistant-mode-card strong {
  font-size: 16px;
  color: var(--color-primary-strong);
}

.assistant-mode-card p {
  margin: 0;
  color: var(--color-text-main);
  font-size: 13px;
  line-height: 1.6;
}

.assistant-mode-card span {
  margin-top: auto;
  color: var(--color-text-sub);
  font-size: 12px;
  line-height: 1.5;
}

.placeholder-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 18px;
  background: var(--color-bg-soft);
}

.workbench-table .vxe-body--row.row-error {
  background: rgba(197, 83, 83, 0.04);
}

.workbench-table .vxe-body--row.row-warning {
  background: rgba(217, 137, 36, 0.05);
}

.workbench-table .vxe-body--row.row-selected {
  background: rgba(29, 111, 165, 0.08);
}

.workbench-table {
  width: 100%;
}

.workbench-table .vxe-header--row {
  background: #f2f7fa;
}

.work-surface {
  min-width: 0;
  background: var(--color-bg-panel);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 16px;
}

.surface-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 14px;
}

.surface-header.compact {
  align-items: center;
  margin-bottom: 12px;
}

.surface-header h2 {
  margin: 0;
  font-size: 18px;
  line-height: 1.2;
}

.surface-header p {
  margin: 6px 0 0;
  color: var(--color-text-sub);
  font-size: 13px;
  line-height: 1.5;
}

.ops-dashboard {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  gap: 16px;
  align-items: start;
}

.ops-main,
.ops-side {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
}

.ops-hero {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
  padding: 18px;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
}

.ops-hero h2 {
  margin: 10px 0 0;
  font-size: 22px;
  line-height: 1.2;
}

.ops-hero p {
  margin: 8px 0 0;
  color: var(--color-text-sub);
}

.ops-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.mini-metric-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.mini-metric {
  display: grid;
  gap: 4px;
  text-align: left;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: #fff;
  padding: 12px;
  cursor: pointer;
}

.mini-metric span,
.mini-metric em {
  color: var(--color-text-sub);
  font-size: 12px;
  font-style: normal;
}

.mini-metric strong {
  color: var(--color-text-main);
  font-size: 24px;
  line-height: 1;
}

.task-queue {
  display: grid;
  gap: 10px;
}

.task-row {
  width: 100%;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) 92px;
  gap: 12px;
  align-items: center;
  text-align: left;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-bg-soft);
  padding: 12px;
  cursor: pointer;
}

.task-row.active {
  border-color: rgba(29, 111, 165, 0.4);
  background: rgba(29, 111, 165, 0.06);
}

.task-row-icon {
  color: var(--color-primary-strong);
  font-size: 20px;
}

.task-row-title {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.task-row-title strong {
  font-size: 15px;
}

.task-row-main p {
  margin: 6px 0 0;
  color: var(--color-text-sub);
  font-size: 13px;
  line-height: 1.5;
}

.task-row-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 8px;
  color: var(--color-text-sub);
  font-size: 12px;
}

.task-row-progress {
  display: grid;
  gap: 4px;
  justify-items: end;
}

.task-row-progress strong {
  font-family: var(--font-data);
  font-size: 20px;
}

.task-row-progress span {
  color: var(--color-text-sub);
  font-size: 12px;
}

.workflow-pair {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.compact-flow {
  display: grid;
  gap: 8px;
}

.compact-flow-step {
  width: 100%;
  display: grid;
  gap: 4px;
  text-align: left;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-bg-soft);
  padding: 10px;
  cursor: pointer;
}

.compact-flow-step.active {
  border-color: rgba(29, 111, 165, 0.38);
  background: rgba(29, 111, 165, 0.07);
}

.compact-flow-step.done {
  border-color: rgba(47, 143, 91, 0.32);
  background: rgba(47, 143, 91, 0.07);
}

.compact-flow-step strong {
  font-size: 14px;
}

.compact-flow-step span {
  color: var(--color-text-sub);
  font-size: 12px;
  line-height: 1.45;
}

.side-panel {
  padding: 14px;
}

.issue-stack,
.quick-link-list,
.area-progress-list {
  display: grid;
  gap: 8px;
}

.issue-card,
.quick-link-row {
  width: 100%;
  display: grid;
  gap: 5px;
  text-align: left;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-bg-soft);
  padding: 10px;
  cursor: pointer;
}

.issue-card.active,
.issue-card:hover,
.quick-link-row:hover {
  border-color: rgba(29, 111, 165, 0.36);
  background: rgba(29, 111, 165, 0.06);
}

.issue-card.compact {
  padding: 9px;
}

.issue-card strong,
.quick-link-row strong {
  color: var(--color-text-main);
  font-size: 13px;
}

.issue-card span,
.quick-link-row span,
.issue-card em {
  color: var(--color-text-sub);
  font-size: 12px;
  font-style: normal;
  line-height: 1.45;
}

.area-progress {
  display: grid;
  gap: 6px;
  padding: 10px;
  border-radius: var(--radius-md);
  background: var(--color-bg-soft);
}

.area-progress div {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
}

.area-progress span {
  color: var(--color-text-sub);
  font-size: 12px;
}

.table-page-shell {
  gap: 12px;
}

.workbook-topbar {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  padding: 14px 16px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: #fff;
}

.workbook-topbar h1 {
  margin: 4px 0 0;
  font-size: 24px;
  line-height: 1.2;
}

.breadcrumb-line {
  color: var(--color-text-sub);
  font-size: 12px;
}

.workbook-status {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  align-items: center;
}

.compact-stage {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.compact-stage .stage-step {
  min-height: 72px;
  padding: 10px 12px;
}

.excel-workbench {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr) 310px;
  gap: 12px;
  align-items: stretch;
  min-height: 700px;
}

.sheet-sidebar,
.spreadsheet-main,
.inspector-panel {
  min-width: 0;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: #fff;
}

.sheet-sidebar {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px;
}

.sidebar-block {
  display: grid;
  gap: 8px;
}

.sidebar-block h2 {
  margin: 0;
  font-size: 14px;
}

.sheet-nav-item,
.area-mini-row {
  width: 100%;
  display: grid;
  gap: 5px;
  text-align: left;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-bg-soft);
  padding: 10px;
  cursor: pointer;
}

.sheet-nav-item.active {
  border-color: rgba(29, 111, 165, 0.4);
  background: rgba(29, 111, 165, 0.07);
}

.sheet-nav-item span,
.area-mini-row strong {
  color: var(--color-text-main);
  font-weight: 700;
  font-size: 13px;
}

.sheet-nav-item em {
  justify-self: start;
  padding: 2px 7px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  font-style: normal;
}

.area-mini-row span {
  color: var(--color-text-sub);
  font-size: 12px;
}

.spreadsheet-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.sheet-toolbar {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 12px 14px;
  border-bottom: 1px solid var(--color-border);
}

.sheet-toolbar strong {
  display: block;
  font-size: 15px;
}

.sheet-toolbar span {
  color: var(--color-text-sub);
  font-size: 12px;
}

.spreadsheet-table {
  flex: 1;
}

.cell-input {
  width: 100%;
}

.formula-cell {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  min-width: 62px;
  color: #60717f;
  font-weight: 700;
}

.cell-note {
  width: 100%;
  min-height: 30px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--color-text-main);
  text-align: left;
  cursor: pointer;
}

.cell-note.warning,
.cell-note.danger {
  color: var(--color-danger);
  font-weight: 700;
}

.cell-danger-text {
  color: var(--color-danger);
  font-weight: 700;
}

.sheet-statusbar {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 9px 12px;
  border-top: 1px solid var(--color-border);
  background: var(--color-bg-soft);
  color: var(--color-text-sub);
  font-size: 12px;
}

.inspector-panel {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.inspector-tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-bottom: 1px solid var(--color-border);
}

.inspector-tabs button {
  border: 0;
  background: #fff;
  padding: 11px 8px;
  color: var(--color-text-sub);
  cursor: pointer;
}

.inspector-tabs button.active {
  color: var(--color-primary-strong);
  font-weight: 700;
  box-shadow: inset 0 -2px 0 var(--color-primary);
}

.inspector-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px;
  overflow: auto;
}

.inspector-title {
  display: flex;
  gap: 8px;
  align-items: center;
  color: var(--color-primary-strong);
}

.inspector-body p {
  margin: 0;
  color: var(--color-text-sub);
  font-size: 13px;
  line-height: 1.55;
}

.rule-item.compact {
  padding: 10px;
}

.rule-item.compact span {
  display: block;
  margin-top: 6px;
  color: var(--color-text-sub);
  font-size: 12px;
}

.compact-code {
  font-size: 12px;
}

.log-list {
  display: grid;
  gap: 8px;
}

.log-row {
  display: grid;
  gap: 4px;
  padding: 10px;
  border-radius: var(--radius-md);
  background: var(--color-bg-soft);
}

.log-row span,
.log-row em {
  color: var(--color-text-sub);
  font-size: 12px;
  font-style: normal;
}

.empty-mini {
  color: var(--color-text-sub);
  font-size: 12px;
  padding: 10px;
  background: var(--color-bg-soft);
  border-radius: var(--radius-md);
}

.quality-summary-strip {
  display: grid;
  grid-template-columns: repeat(4, 110px) minmax(0, 1fr);
  gap: 10px;
  align-items: stretch;
}

.quality-pill {
  display: grid;
  gap: 4px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: #fff;
  padding: 10px 12px;
}

.quality-pill span {
  color: var(--color-text-sub);
  font-size: 12px;
}

.quality-pill strong {
  font-family: var(--font-data);
  font-size: 22px;
  line-height: 1;
}

.quality-pill.warning strong {
  color: var(--color-warning);
}

.quality-pill.danger strong {
  color: var(--color-danger);
}

.quality-source {
  display: flex;
  align-items: center;
  border: 1px dashed rgba(29, 111, 165, 0.35);
  border-radius: var(--radius-md);
  background: rgba(29, 111, 165, 0.06);
  color: var(--color-primary-strong);
  padding: 10px 12px;
  font-size: 12px;
  line-height: 1.5;
}

.field-group-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--color-border);
  background: #fbfdff;
}

.field-group-strip span {
  padding: 4px 8px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text-sub);
  font-size: 12px;
}

@media (max-width: 1400px) {
  .metric-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .quad-grid,
  .flow-strip,
  .stage-rail,
  .dense-grid,
  .mini-metric-strip,
  .task-meta-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ops-dashboard {
    grid-template-columns: minmax(0, 1fr) 320px;
  }

  .excel-workbench {
    grid-template-columns: 220px minmax(0, 1fr) 290px;
  }

  .quality-summary-strip {
    grid-template-columns: repeat(4, minmax(96px, 1fr));
  }

  .quality-source {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1100px) {
  .split-grid,
  .workbench-grid,
  .table-workspace,
  .dual-grid,
  .triple-grid,
  .hero-task-panel,
  .ops-dashboard,
  .workflow-pair,
  .task-focus {
    grid-template-columns: 1fr;
  }

  .metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .excel-workbench {
    grid-template-columns: 1fr;
    min-height: 0;
  }

  .sheet-sidebar,
  .spreadsheet-main,
  .inspector-panel {
    min-height: auto;
  }

  .spreadsheet-main {
    min-height: 520px;
  }

  .sheet-toolbar,
  .surface-header,
  .ops-hero,
  .workbook-topbar {
    flex-wrap: wrap;
  }

  .task-row {
    grid-template-columns: 32px minmax(0, 1fr);
  }

  .task-row-progress {
    grid-column: 2;
    justify-items: start;
  }
