+  grid-template-columns: 84px minmax(0, 1fr);
+  gap: 10px;
+  align-items: start;
+  padding: 8px 0;
+  border-bottom: 1px solid var(--color-border);
+}
+
+.trace-row span {
+  color: var(--color-text-sub);
+  font-size: 12px;
+}
+
+.trace-row strong {
+  color: var(--color-text-main);
+  font-size: 13px;
+  line-height: 1.5;
+}
+
+.cell-input {
+  width: 92px;
+}
+
+.cell-note {
+  border: 0;
+  background: transparent;
+  color: var(--color-primary-strong);
+  cursor: pointer;
+  text-align: left;
+}
+
+.cell-note.warning {
+  color: var(--color-warning);
+}
+
+.cell-note.danger,
+.cell-danger-text {
+  color: var(--color-danger);
+  font-weight: 700;
+}
+
+.formula-cell {
+  color: var(--color-text-sub);
+  font-family: var(--font-data);
+}
+
